import { describe, expect, test } from 'bun:test';
import { DomainError } from '@agentic-ddd/core';
import { covers } from '@agentic-ddd/testing';
import { Task } from '../domain/task';
import { TaskCompleted } from '../domain/task.events';

describe('Task.complete', () => {
  test(
    covers(
      ['criterion:0001/conclusao', 'method:Task.complete'],
      'registra TaskCompleted, muda para completed e rejeita repeticao com TASK_ALREADY_COMPLETED',
    ),
    () => {
      const task = Task.create('t1', 'Minha tarefa');
      task.pullEvents();

      task.complete();

      expect(task.status).toBe('completed');
      const [event] = task.pullEvents();
      expect(event).toBeInstanceOf(TaskCompleted);
      expect(event?.payload).toEqual({ taskId: 't1' });

      try {
        task.complete();
        throw new Error('Expected Task.complete to throw');
      } catch (error) {
        expect(error).toBeInstanceOf(DomainError);
        expect((error as DomainError).code).toBe('TASK_ALREADY_COMPLETED');
      }
    },
  );
});
